from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];h=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();p.set_content(h.decode());p.wait_for_function('window.INKDuel?.ready&&INK.MovementStrike')
 result=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state;A.start('ryu','ken','training','classic',4);G.paused=false;document.getElementById('dummy').value='idle';document.getElementById('autohp').checked=false;A.teleport(0,500);A.teleport(1,690);A.step();A.press(0,'right');A.press(0,'RUSH');A.press(1,'LP');A.step(2);A.press(0,'MP');let plan=null,spentBefore=0,budget=0,interrupt=null;for(let i=0;i<20;i++){A.step();const f=A.fighters[0];if(f._inkMovementStrike){plan=f._inkMovementStrike;spentBefore=plan.spent;budget=plan.budget;}if(plan&&f.state==='hit'){interrupt={state:f.state,spent:plan.spent,budget,remaining:plan.remaining,cleared:!f._inkMovementStrike,hitstop:G.hitstop};const stopped=plan.spent;A.step(4);interrupt.stable=plan.spent===stopped;break;}}
 const cpu=[];for(let seed=1;seed<=4;seed++){document.getElementById('difficulty').value='hard';A.start('ryu','ken','demo','classic',seed);G.paused=false;A.teleport(0,200);A.teleport(1,1240);A.step(120);G.mode='training';document.getElementById('dummy').value='idle';for(let i=0;i<100&&A.fighters[0].state!=='idle';i++)A.step();A.teleport(0,500);A.teleport(1,800);A.press(0,'RUSH');A.release(0,'RUSH');G.mode='demo';const entry=A.fighters[0].state,seen=new Set(),moves=[],states=[];for(let i=0;i<40;i++){A.step();if(i<12)states.push({i,state:A.fighters[0].state,move:A.fighters[0].attack?.m.id,age:A.fighters[0].stateAge,x:A.fighters[0].x});for(const f of A.fighters){const a=f.attack,q=a?.m.movementStrike;if(q&&!seen.has(a)){seen.add(a);moves.push({actor:f.index,move:a.m.id,source:q.source,budget:q.budget,held:[...f.input.held],dir:q.dir});}}}cpu.push({seed,entry,moves,states});}return {interrupt,cpu};}''');b.close()
r={'sha256':hashlib.sha256(h).hexdigest(),**result};(R/'qa/movement-strike/interrupt-cpu.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2));assert result['interrupt'] and result['interrupt']['spent']<result['interrupt']['budget'] and result['interrupt']['cleared'] and result['interrupt']['stable'];assert any(x['moves'] for x in result['cpu'])
